package com.mylegnd.legend.registered.data

import com.mylegnd.legend.registered.core.model.*
import com.mylegnd.legend.registered.core.network.*
import android.content.Context
import android.net.Uri
import com.mylegnd.legend.registered.core.media.SocialMediaUploader

sealed interface LoadState<out T> { data object Idle : LoadState<Nothing>; data object Loading : LoadState<Nothing>; data class Data<T>(val value: T) : LoadState<T>; data class Error(val message: String) : LoadState<Nothing> }
private suspend fun <T> request(block: suspend () -> T): LoadState<T> = runCatching { LoadState.Data(block()) }.getOrElse { LoadState.Error((it as? LegendApiException)?.problem?.message ?: "Legend is unavailable right now.") }
class HomeRepository(private val client: LegendApiClient) { suspend fun load(role: String) = request { client.api.home(role).legendBody() } }
class FinancialRepository(private val client: LegendApiClient) { suspend fun load(role: String) = request { client.api.financial(role).legendBody() } }
class AccountRepository(private val client: LegendApiClient) { suspend fun profile(role: String) = request { client.api.account(role).legendBody() }; suspend fun lifecycle(role: String) = request { client.api.lifecycle(role).legendBody() }; suspend fun update(role: String, update: AccountUpdateRequest) = request { client.api.updateAccount(role, update).legendBody() }; suspend fun updatePrivacy(role: String, isPrivate: Boolean) = request { client.api.updatePrivacy(role, AccountPrivacyUpdateRequest(isPrivate)).legendBody() }; suspend fun requestDeletion(role: String, confirmation: String) = request { client.api.deletionRequest(role, ConfirmationRequest(confirmation)).legendBody() } }
class MessagingRepository(private val client: LegendApiClient) { suspend fun conversations(role: String) = request { client.api.conversations(role).legendBody() }; suspend fun messages(role: String, id: String) = request { client.api.messages(role, id).legendBody() }; suspend fun send(role: String, id: String, text: String) = request { client.api.sendMessage(role, id, SendMessageRequest(text)).legendBody() }; suspend fun markRead(role: String, id: String) = request { client.api.markRead(role, id).legendBody() } }
class SocialRepository(private val client: LegendApiClient) { private val uploader = SocialMediaUploader(client); suspend fun feed(role: String) = request { client.api.socialFeed(role).legendBody() }; suspend fun createPost(role: String, type: String, body: String, audience: String?) = request { client.api.createPost(role, CreateSocialPostRequest(type, body, audience)).legendBody() }; suspend fun createMediaPost(context: Context, role: String, uris: List<Uri>, type: String, body: String, audience: String) = request { uploader.upload(context, role, uris, type, body, audience) }; suspend fun react(role: String, id: String) = request { client.api.react(role, id).legendBody() }; suspend fun comment(role: String, id: String, body: String) = request { client.api.comment(role, id, CreateSocialCommentRequest(body)).legendBody() } }
class DiscoveryRepository(private val client: LegendApiClient) { suspend fun search(role: String, query: String? = null, offset: Int = 0, pageSize: Int = 24, sort: String? = null) = request { client.api.discovery(role, query, offset, pageSize, sort).legendBody() } }
class JourneyRepository(private val client: LegendApiClient) { suspend fun dashboard(role: String) = request { client.api.journeyCircles(role).legendBody() }; suspend fun requestConnection(role: String, clientProfileId: String, reason: String? = null, introduction: String? = null) = request { client.api.requestJourneyConnection(role, JourneyConnectionRequest(clientProfileId, reason, introduction)).legendBody() } }
class CommunityRepository(private val client: LegendApiClient) { suspend fun block(role: String, userId: String, participantType: String) = request { client.api.block(role, CommunityBlockRequest(userId, participantType)).legendBody() }; suspend fun report(role: String, userId: String, participantType: String, targetKind: String, targetEntityId: String?, category: String, detail: String) = request { client.api.report(role, CommunityReportRequest(userId, participantType, targetKind, targetEntityId, category, detail)).legendBody() } }
class NotificationDeviceRepository(private val client: LegendApiClient) {
    suspend fun registerFcm(role: String, token: String) = request { client.api.registerFcmDevice(role, FcmDeviceTokenRequest(token)).legendBody() }
    suspend fun deactivateFcm(role: String, token: String) = request { client.api.deactivateFcmDevice(role, FcmDeviceTokenRequest(token)).legendBody() }
}
